#include "document.h"
#include "layer_compositor.h"
#include <iostream>
#include <algorithm>
using namespace moon;
void duplicateRowsCheck(){
 Document d(1,1);d.beginStroke({0,0},0xff123456);d.commitStroke();const auto bottom=d.layer().id;d.addLinkedFrame();const auto aliasFrame=d.frame().id;d.addLayer();const auto middle=d.layer().id;d.addLayer();const auto top=d.layer().id;d.beginStroke({0,0},0xffabcdef);d.commitStroke();d.setLayerVisible(false);d.setLayerLocked(true);d.selectTimelineLayer(bottom);d.selectTimelineLayer(top,1);
 const auto before=d.timeline().state();const auto selected=d.timelineSelection().layers;const auto active=d.layer().id;const auto h=d.historySize();if(!d.canDuplicateSelectedLayers())throw std::runtime_error("duplicate locked/hidden allowed");d.duplicateSelectedLayers();const auto copies=d.timelineSelection().layers;
 if(copies.size()!=2 || d.historySize()!=h+1 || d.layer().id!=copies.front() || d.timeline().state().layers[2].id!=top || d.timeline().state().layers[3].id!=middle || d.timeline().state().layers[4].id!=bottom || d.frame().id!=aliasFrame)throw std::runtime_error("duplicate row placement");
 if(d.timeline().state().layers[0].name!=before.layers[0].name+U" 副本" || d.timeline().state().layers[0].visible || !d.timeline().state().layers[0].locked)throw std::runtime_error("duplicate properties");
 const auto* copied=d.timeline().findCel(copies.back(),aliasFrame);if(!copied || copied->linkedCelId || copied->runtimeSharedCelId || !copied->surface || copied->surface->pixels[0]!=0xff123456)throw std::runtime_error("duplicate resolved independent cel");
 d.undo();if(d.layer().id!=active || d.timelineSelection().layers!=selected || d.timeline().state().cels.size()!=before.cels.size())throw std::runtime_error("duplicate undo");d.redo();if(d.timelineSelection().layers!=copies)throw std::runtime_error("duplicate redo");d.selectLayer(copies.back());d.beginStroke({0,0},0xff556677);d.commitStroke();d.selectLayer(bottom);if(d.pixels()[0]!=0xff123456)throw std::runtime_error("duplicate copy shares source");d.clearTimelineSelection();const auto rev=d.revision();d.duplicateSelectedLayers();if(d.canDuplicateSelectedLayers() || d.revision()!=rev)throw std::runtime_error("duplicate empty selection");
}
void selectedMergeCheck(){
 Document d(1,1);d.beginStroke({0,0},0xff112233);d.commitStroke();const auto bottom=d.layer().id;d.addLayer();d.beginStroke({0,0},0x80445566);d.commitStroke();const auto middle=d.layer().id;d.addLayer();d.beginStroke({0,0},0x80778899);d.commitStroke();const auto top=d.layer().id;const auto name=d.layer().name;d.addLinkedFrame(true);const auto activeFrame=d.frame().id;d.addLayer();const auto unselected=d.layer().id;d.setLayerVisible(false);d.selectTimelineLayer(bottom);d.selectTimelineLayer(top,1);d.selectTimelineLayer(middle,1);
 const auto original=d.timeline().state();const auto selection=d.timelineSelection().layers;const auto active=d.layer().id;std::vector<Pixel> expected;for(const auto& frame:original.frames)expected.push_back(compositeNormalRegion(d.timeline(),frame.id,{0,0,1,1})[0]);const auto h=d.historySize();if(!d.canMergeSelectedLayers())throw std::runtime_error("selected merge enabled");d.mergeSelectedLayers();const auto merged=d.layer().id;
 if(d.historySize()!=h+1 || d.timeline().state().layers.size()!=2 || d.timeline().state().layers.front().id!=unselected || d.layer().name!=name+U" 合并" || d.frame().id!=activeFrame || d.timelineSelection().layers!=std::vector<std::string>{merged})throw std::runtime_error("selected merge structure");
 for(std::size_t i=0;i<original.frames.size();++i){d.selectFrame(original.frames[i].id);if(d.pixels()[0]!=expected[i])throw std::runtime_error("selected merge linked pixels");}d.undo();if(d.layer().id!=active || d.frame().id!=activeFrame || d.timelineSelection().layers!=selection || d.timeline().state().cels.size()!=original.cels.size())throw std::runtime_error("selected merge undo");d.redo();if(d.layer().id!=merged || d.timelineSelection().layers!=std::vector<std::string>{merged})throw std::runtime_error("selected merge redo");d.undo();
 d.selectTimelineLayer(top);d.selectTimelineLayer(bottom,1);if(d.canMergeSelectedLayers())throw std::runtime_error("selected sparse admitted");const auto rev=d.revision();bool rejected=false;try{d.mergeSelectedLayers();}catch(const std::runtime_error&){rejected=true;}if(!rejected || d.revision()!=rev)throw std::runtime_error("selected sparse mutation");
 d.selectTimelineLayer(top);d.selectTimelineLayer(middle,1);d.selectLayer(middle);d.setLayerLocked(true);if(d.canMergeSelectedLayers())throw std::runtime_error("selected locked admitted");d.setLayerLocked(false);d.setLayerVisible(false);if(d.canMergeSelectedLayers())throw std::runtime_error("selected hidden admitted");d.setLayerVisible(true);d.selectTimelineLayer(top);if(d.canMergeSelectedLayers())throw std::runtime_error("selected single admitted");
}
void downMergeCheck(){
 Document d(2,1);d.beginStroke({0,0},0xff112233);d.commitStroke();const auto bottom=d.layer().id;d.addLayer();d.beginStroke({0,0},0x80445566);d.commitStroke();d.setLayerOpacity(.5);const auto top=d.layer().id;const auto name=d.layer().name;d.addLinkedFrame(true);d.setFrameDuration(275);const auto activeFrame=d.frame().id;d.addLayer();const auto untouched=d.layer().id;d.beginStroke({1,0},0xffabcdef);d.commitStroke();d.selectTimelineLayer(top);d.selectTimelineLayer(bottom,1);d.selectLayer(top);
 const auto before=d.timeline().state();const auto selection=d.timelineSelection();std::vector<std::vector<Pixel>> expected;
 auto pair=before;pair.layers.erase(pair.layers.begin());pair.cels.erase(std::remove_if(pair.cels.begin(),pair.cels.end(),[&](const auto& c){return c.layerId==untouched;}),pair.cels.end());timeline::Timeline pairTimeline(pair);
 for(const auto& frame:before.frames)expected.push_back(compositeNormalRegion(pairTimeline,frame.id,{0,0,2,1}));
 const auto h=d.historySize();if(!d.canMergeLayerDown())throw std::runtime_error("down enabled");d.mergeLayerDown();const auto merged=d.layer().id;
 if(d.historySize()!=h+1 || d.layer().name!=name+U" 合并" || d.frame().id!=activeFrame || d.timeline().state().layers.front().id!=untouched || d.timelineSelection().layers!=std::vector<std::string>{merged})throw std::runtime_error("down identity/UI");
 for(std::size_t i=0;i<before.frames.size();++i){d.selectFrame(before.frames[i].id);if(d.pixels()!=expected[i])throw std::runtime_error("down linked multi-frame composition");}
 d.undo();if(d.timeline().state().cels.size()!=before.cels.size() || d.layer().id!=top || d.frame().id!=activeFrame || d.timelineSelection().layers!=selection.layers)throw std::runtime_error("down undo selection");d.redo();if(d.layer().id!=merged || d.timelineSelection().layers!=std::vector<std::string>{merged})throw std::runtime_error("down redo selection");d.undo();
 for(int mode=0;mode<3;++mode){d.selectLayer(mode==2?bottom:top);if(mode==0)d.setLayerVisible(false);if(mode==1)d.setLayerLocked(true);const auto rev=d.revision();if(d.canMergeLayerDown())throw std::runtime_error("down invalid enabled");bool rejected=false;try{d.mergeLayerDown();}catch(const std::runtime_error&){rejected=true;}if(!rejected || d.revision()!=rev)throw std::runtime_error("down rejected transaction");if(mode==0)d.setLayerVisible(true);if(mode==1)d.setLayerLocked(false);}
}
void visibleMergeCheck(){Document d(2,1);d.beginStroke({0,0},0xff0000ff);d.commitStroke();d.addLayer();d.beginStroke({0,0},0x8000ff00);d.commitStroke();d.setLayerOpacity(.5);d.addLayer();d.beginStroke({1,0},0xff123456);d.commitStroke();const auto hidden=d.layer().id;d.setLayerVisible(false);d.addFrame();d.selectLayer(d.timeline().state().layers.back().id);d.beginStroke({1,0},0xffff0000);d.commitStroke();std::vector<std::vector<Pixel>> expected;for(const auto& f:d.timeline().state().frames)expected.push_back(compositeNormalRegion(d.timeline(),f.id,{0,0,2,1}));auto before=d.timeline().state();auto h=d.historySize();d.mergeVisibleLayers();if(d.historySize()!=h+1||d.timeline().state().layers.size()!=2||d.timeline().state().layers[1].id!=hidden||d.timeline().state().layers[1].visible)throw std::runtime_error("visible hidden preservation");for(std::size_t i=0;i<expected.size();++i){d.selectFrame(before.frames[i].id);if(d.pixels()!=expected[i])throw std::runtime_error("visible multi-frame composition");}d.undo();if(d.timeline().state().layers.size()!=3||d.timeline().state().cels.size()!=before.cels.size())throw std::runtime_error("visible undo");d.redo();if(d.timeline().state().layers.size()!=2)throw std::runtime_error("visible redo");d.undo();d.selectLayer(before.layers.back().id);d.setLayerLocked(true);auto rev=d.revision();try{d.mergeVisibleLayers();throw std::runtime_error("visible locked admitted");}catch(const std::runtime_error& e){if(std::string(e.what())=="visible locked admitted")throw;}if(d.revision()!=rev)throw std::runtime_error("visible rejection mutated");}
int main(){try{duplicateRowsCheck();selectedMergeCheck();downMergeCheck();visibleMergeCheck();Document d(2,1);d.beginStroke({0,0},0xff0000ff);d.commitStroke();d.addLayer();d.beginStroke({0,0},0x8000ff00);d.commitStroke();d.setLayerOpacity(.5);d.selectLayer(d.timeline().state().layers[0].id);d.addFrame();d.selectFrame(d.timeline().state().frames[1].id);d.beginStroke({1,0},0xffff0000);d.commitStroke();auto before=d.timeline().state().layers.size();d.mergeLayerDown();std::cerr<<"layers="<<d.timeline().state().layers.size()<<" before="<<before<<" p0="<<std::hex<<d.pixels()[0]<<" p1="<<d.pixels()[1]<<std::dec<<"\\n";if(d.timeline().state().layers.size()!=before-1||d.pixels()[1]==0)throw std::runtime_error("merge pixels");d.undo();if(d.timeline().state().layers.size()!=before)throw std::runtime_error("merge undo");Document f(2,1); f.beginStroke({0,0},0xff112233); f.commitStroke(); f.setFrameDuration(321); f.selectFrameHeader(f.frame().id); if(!f.copySelectedFrames()) throw std::runtime_error("frame copy"); auto src=f.pixels()[0]; f.deleteFrame(); if(!f.pasteCopiedFrames() || f.pixels()[0]!=src || f.frame().duration!=321) throw std::runtime_error("frame snapshot"); f.undo(); if(f.timeline().state().frames.size()!=1) throw std::runtime_error("frame undo"); std::cout<<"layer merge and frame snapshot checks passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
